const { body, headers } = $input.first().json;
const repo = body?.repository;
if (repo?.full_name?.toLowerCase() !== 'glebtv43/itmov2' || body.sender?.type === 'Bot') return [];
const event = headers?.['x-github-event'];
const comment = body.comment?.body?.trim();
let mode;
let number;
if (event === 'pull_request' && body.action === 'opened') {
  if (body.pull_request.base.ref !== '7.1') return [];
  mode = 'main';
  number = body.number;
} else if (event === 'issue_comment' && body.action === 'created' && body.issue?.pull_request) {
  if (!['OWNER', 'MEMBER', 'COLLABORATOR'].includes(body.comment.author_association)) return [];
  if (comment === '/make_ai_review') mode = 'main';
  if (comment === '/make_other_ai_review') mode = 'other';
  number = body.issue.number;
}
if (!mode || !Number.isSafeInteger(number) || number < 1) return [];
return [{ json: {
  mode,
  number,
  model: mode === 'main' ? 'openai/gpt-5' : 'anthropic/claude-sonnet-4',
  pr_url: 'https://api.github.com/repos/GlebTV43/ITMOv2/pulls/' + number,
} }];

const pr = $input.first().json;
const event = $('Choose review model').first().json;
if (pr.state !== 'open' || pr.base.ref !== '7.1' || pr.number !== event.number) return [];
if (!Number.isSafeInteger(pr.id) || !/^[a-f0-9]{40}$/.test(pr.head.sha)) {
  throw new Error('GitHub returned an invalid PR ID or head SHA.');
}
return [{ json: { ...event, pr_id: String(pr.id), head: pr.head.sha, changed_files: pr.changed_files } }];

const review = $('Check review scope').first().json;
if (review.mode === 'main' && $input.first().json.pr_id === review.pr_id) return [];
return [{ json: review }];

const review = $('Check review scope').first().json;
const files = $input.all().flatMap(item => item.json.body ?? item.json);
if (files.length !== review.changed_files) throw new Error('GitHub did not return the complete file list.');
const hunks = [];
const omitted = [];
for (const file of files) {
  if (!file.patch || !file.filename) {
    if (file.filename) omitted.push(file.filename);
    continue;
  }
  let hunk, oldLine, newLine, oldEnd, newEnd;
  let additions = 0, deletions = 0;
  function finish() {
    if (!hunk) return;
    if (oldLine !== oldEnd || newLine !== newEnd) {
      throw new Error('Incomplete textual patch from GitHub for ' + file.filename);
    }
    const anchor = hunk.right || hunk.left;
    if (anchor) hunks.push({ path: file.filename, ...anchor, patch: hunk.lines.join('\n') });
  }
  for (const line of file.patch.replace(/\r\n/g, '\n').split('\n')) {
    const header = line.match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
    if (header) {
      finish();
      oldLine = Number(header[1]);
      newLine = Number(header[3]);
      oldEnd = oldLine + Number(header[2] ?? 1);
      newEnd = newLine + Number(header[4] ?? 1);
      hunk = { lines: [line] };
    } else if (hunk) {
      hunk.lines.push(line);
      if (line.startsWith('+')) {
        hunk.right ??= { line: newLine, side: 'RIGHT' };
        newLine++;
        additions++;
      } else if (line.startsWith('-')) {
        hunk.left ??= { line: oldLine, side: 'LEFT' };
        oldLine++;
        deletions++;
      } else if (line.startsWith(' ')) {
        oldLine++;
        newLine++;
      }
    }
  }
  finish();
  if (additions !== file.additions || deletions !== file.deletions) {
    throw new Error('GitHub omitted textual changes for ' + file.filename);
  }
}
if (!hunks.length) throw new Error('No textual hunks to review.');
if (hunks.length > 40 || hunks.some(hunk => hunk.patch.length > 16000)) {
  throw new Error('Split this PR into smaller changes before AI review.');
}
return hunks.map((hunk, index) => ({ json: { ...hunk, index, model: review.model, omitted } }));

