const anchors = $('Split diff into hunks').all();
const outputs = $input.all();
if (anchors.length !== outputs.length) throw new Error('VseLLM did not return one response per hunk.');
const comments = outputs.map((item, index) => {
  const { path, line, side } = anchors[index].json;
  const result = item.json.choices?.[0]?.message?.content?.trim();
  if (!result) throw new Error('Empty model response for ' + path);
  const safe = result.replace(/@/g, '＠').replace(/</g, '＜').replace(/>/g, '＞');
  return { path, line, side, body: safe.slice(0, 3500) };
});
const review = $('Check review scope').first().json;
const omitted = anchors[0].json.omitted;
const notes = omitted.length ? ' Файлы без текстового diff: ' + omitted.length + '.' : '';
return [{ json: {
  ...review,
  review: {
    commit_id: review.head,
    event: 'COMMENT',
    body: 'AI-ревью · ' + review.model + ' · блоков diff: ' + comments.length + '.' + notes,
    comments,
  },
} }];

const built = $('Build inline GitHub review').first().json;
const fresh = $input.first().json;
if (fresh.state !== 'open' || fresh.head.sha !== built.head || fresh.base.ref !== '7.1') {
  throw new Error('The PR changed during review. Run the review again on the new diff.');
}
return [{ json: built }];

const githubReview = $input.first().json;
const { pr_id, number, model, head } = $('Check review scope').first().json;
if (!githubReview.id || !githubReview.html_url) throw new Error('GitHub did not confirm publishing.');
return [{ json: { pr_id, pr_number: number, model, head_sha: head, review_url: githubReview.html_url } }];
